#!/usr/bin/env Rscript
#
# Export golden intermediate values from the R DENR reference implementation.
#
# This is plan Phase 0: freeze the reference behavior as fixtures so the Python
# implementation can be checked against it without needing R at test time.
#
# The inputs are generated by the Python side, not taken from DENR's own
# inst/extdata, because that package's LICENSE.md (MIT) and DESCRIPTION
# (GPL >=2) disagree and redistributing its fixtures is what Phase 0 defers.
# What this script writes is *program output*, which is safe to commit.
#
# Usage
# -----
#   # 1. Generate the inputs (from the repository root):
#   uv run python -m tests.fixtures.generate --output build/parity-inputs
#
#   # 2. Run this inside the reference environment. The DENR README publishes a
#   #    container, which is the frozen environment Phase 0 asks for:
#   singularity pull library://rhassett-cshl/stadyum/denr:latest
#   singularity exec denr_latest.sif Rscript scripts/export_r_golden.R \
#       --inputs build/parity-inputs --output tests/fixtures/parity
#
#   # Or, with DENR installed in a local R:
#   Rscript scripts/export_r_golden.R --inputs build/parity-inputs \
#       --output tests/fixtures/parity
#
# Record the DENR commit used; it is written into each golden file as
# `reference_commit` and the Python side reports it on mismatch.

suppressPackageStartupMessages({
  library(DENR)
  library(GenomicFeatures)
  library(jsonlite)
})

args <- commandArgs(trailingOnly = TRUE)
get_arg <- function(flag, default = NULL) {
  hit <- which(args == flag)
  if (length(hit) == 0) {
    if (is.null(default)) stop(paste("missing required argument", flag))
    return(default)
  }
  args[[hit + 1]]
}

inputs_dir <- get_arg("--inputs")
output_dir <- get_arg("--output")
reference_commit <- get_arg("--commit", "unknown")
dir.create(output_dir, showWarnings = FALSE, recursive = TRUE)

spec_path <- file.path(inputs_dir, "scenarios.json")
if (!file.exists(spec_path)) {
  stop(paste(spec_path, "not found; run tests.fixtures.generate first"))
}
scenarios <- jsonlite::fromJSON(spec_path, simplifyDataFrame = FALSE)

#' Convert a GRanges to a plain data frame in 0-based half-open coordinates.
#'
#' GRanges is 1-based inclusive. Emitting 0-based half-open here means the
#' Python side compares numbers directly rather than re-deriving a convention,
#' which is where an off-by-one would otherwise hide.
#' Build a TxDb from a GTF, across Bioconductor versions.
#'
#' `makeTxDbFromGFF` moved from GenomicFeatures to the txdbmaker package and is
#' defunct in GenomicFeatures >= 1.61.1. The published DENR container predates
#' that split, so both spellings are supported rather than pinning one and
#' making this script work in only one of the two reference environments.
txdb_from_gtf <- function(path) {
  if (requireNamespace("txdbmaker", quietly = TRUE)) {
    return(suppressWarnings(txdbmaker::makeTxDbFromGFF(path, format = "gtf")))
  }
  suppressWarnings(GenomicFeatures::makeTxDbFromGFF(path, format = "gtf"))
}

granges_to_frame <- function(gr) {
  data.frame(
    contig = as.character(GenomicRanges::seqnames(gr)),
    start = GenomicRanges::start(gr) - 1L,
    end = GenomicRanges::end(gr),
    strand = as.character(GenomicRanges::strand(gr)),
    stringsAsFactors = FALSE
  )
}

export_one <- function(scenario) {
  name <- scenario$name
  message("scenario: ", name)

  gtf <- file.path(inputs_dir, paste0(name, ".gtf"))
  bw_plus <- file.path(inputs_dir, paste0(name, "_plus.bw"))
  bw_minus <- file.path(inputs_dir, paste0(name, "_minus.bw"))

  txdb <- txdb_from_gtf(gtf)
  transcripts <- GenomicFeatures::transcripts(txdb, columns = c("tx_name", "gene_id"))
  transcripts$gene_id <- as.character(unlist(transcripts$gene_id))

  mask_start <- unlist(scenario$mask_start_bins)
  mask_end <- unlist(scenario$mask_end_bins)
  distance <- if (is.null(scenario$distance)) scenario$bin_size else scenario$distance

  tq <- suppressMessages(DENR::transcript_quantifier(
    transcripts,
    transcript_name_column = "tx_name",
    gene_name_column = "gene_id",
    bin_size = as.integer(scenario$bin_size),
    distance = as.integer(distance),
    mask_start_bins = as.integer(mask_start),
    mask_end_bins = as.integer(mask_end),
    bin_operation = scenario$bin_operation
  ))

  tq <- suppressMessages(DENR::add_data(
    tq = tq, bigwig_plus = bw_plus, bigwig_minus = bw_minus
  ))
  fitted <- suppressMessages(DENR::fit(
    tq, transform = scenario$transform, heuristic_inactive_override = FALSE
  ))

  # Per-locus geometry.
  #
  # Everything is indexed *positionally*. bins, models, counts and masks are
  # all named by group id, but `fit()` builds abundances with
  # `estim <- list(); estim[[i]] <- ...`, which produces an UNNAMED list, so
  # name-based lookup of model_abundance silently fails. The lists are built in
  # the same order, which the stopifnot below verifies.
  locus_names <- names(tq@bins)
  stopifnot(identical(names(tq@models), locus_names))
  stopifnot(identical(names(tq@counts), locus_names))
  stopifnot(length(fitted@model_abundance) == length(locus_names))

  loci <- lapply(seq_along(locus_names), function(i) {
    locus <- locus_names[[i]]
    bins <- granges_to_frame(tq@bins[[i]])
    models <- tq@models[[i]]
    list(
      locus_key = locus,
      bin_starts = bins$start,
      bin_ends = bins$end,
      contig = unique(bins$contig),
      strand = unique(bins$strand),
      n_bins = nrow(models),
      n_models = ncol(models),
      # Column-major flattening; the Python side reshapes with order="F".
      models = as.numeric(models),
      model_colnames = colnames(models),
      counts = as.numeric(tq@counts[[i]]),
      masked_bins_0based = sort(as.integer(tq@masks[[i]]) - 1L),
      abundance = as.numeric(fitted@model_abundance[[i]]),
      objective = DENR:::sum_squares_lasso(
        fitted@model_abundance[[i]],
        models,
        DENR:::mask_data(tq@counts[[i]], tq@masks[[i]]),
        lambda = 0,
        transform = scenario$transform
      ),
      predicted = as.numeric(models %*% fitted@model_abundance[[i]])
    )
  })
  names(loci) <- locus_names

  key <- tq@transcript_model_key
  list(
    scenario = name,
    reference_commit = reference_commit,
    denr_version = as.character(utils::packageVersion("DENR")),
    r_version = as.character(getRversion()),
    config = list(
      bin_size = scenario$bin_size,
      distance = distance,
      mask_start_bins = mask_start,
      mask_end_bins = mask_end,
      bin_operation = scenario$bin_operation,
      transform = scenario$transform
    ),
    transcripts = granges_to_frame(transcripts),
    transcript_names = as.character(transcripts$tx_name),
    transcript_model_key = list(
      tx_name = as.character(key$tx_name),
      group = as.integer(key$group),
      model = as.integer(key$model)
    ),
    loci = loci
  )
}

for (scenario in scenarios) {
  golden <- tryCatch(export_one(scenario), error = function(e) {
    message("  FAILED: ", conditionMessage(e))
    NULL
  })
  if (is.null(golden)) next
  out <- file.path(output_dir, paste0(scenario$name, ".json"))
  # digits = NA keeps full double precision; a fixed digit count would round
  # away exactly the differences a parity test exists to detect.
  write(jsonlite::toJSON(golden, auto_unbox = TRUE, digits = NA, null = "null"), out)
  message("  wrote ", out)
}

message("done")
